const p = $json.body ?? $json;
const allowed = ['sheet', 'email', 'whatsapp', 'task', 'study', 'calendar'];
if (!allowed.includes(p.action)) throw new Error('Acción no válida');
const content = String(p.content ?? '').trim();
if (!content) throw new Error('El contenido está vacío');
if (content.length > 10000) throw new Error('El contenido supera 10 000 caracteres');
const urgentWords = /urgente|hoy|inmediato|prioridad alta|asap/i;
const mediumWords = /mañana|esta semana|pendiente|importante/i;
const priority = urgentWords.test(content) ? 'alta' : mediumWords.test(content) ? 'media' : 'normal';
const labels = { sheet: 'Registro local', email: 'Borrador de email', whatsapp: 'Borrador de WhatsApp', task: 'Plan de tareas', study: 'Sesión de estudio', calendar: 'Evento de calendario' };
return [{ json: { requestId: `nx-${Date.now().toString(36)}`, action: p.action, actionLabel: labels[p.action], recipient: String(p.recipient ?? '').trim(), subject: String(p.subject ?? 'Solicitud NEXORA').trim(), content, priority, source: 'NEXORA AI', receivedAt: new Date().toISOString(), approvalRequired: ['email', 'whatsapp', 'calendar'].includes(p.action) } }];

const fs = require('fs');
const file = '/files/nexora-events.jsonl';
for (const item of items) fs.appendFileSync(file, `${JSON.stringify(item.json)}\n`, 'utf8');
return items.map(item => ({ json: { ...item.json, storedLocally: true, localFile: file } }));

const p = $json;
const lines = p.content.split(/\n|[.;](?:\s+|$)/).map(x => x.trim()).filter(Boolean).slice(0, 8);
let automation;
switch (p.action) {
  case 'sheet': automation = { type: 'local_record', columns: { id: p.requestId, fecha: p.receivedAt, asunto: p.subject, contenido: p.content, prioridad: p.priority } }; break;
  case 'email': automation = { type: 'email_draft', to: p.recipient || 'POR DEFINIR', subject: p.subject, body: p.content, status: 'esperando aprobación humana' }; break;
  case 'whatsapp': automation = { type: 'whatsapp_draft', to: p.recipient || 'POR DEFINIR', message: p.content, status: 'esperando aprobación humana' }; break;
  case 'task': automation = { type: 'task_plan', priority: p.priority, checklist: lines.map((text, index) => ({ order: index + 1, text, done: false })) }; break;
  case 'study': automation = { type: 'study_session', blocks: [{ minutes: 10, activity: 'Lectura y conceptos', material: p.content }, { minutes: 20, activity: 'Práctica activa', material: 'Explicar sin mirar y crear ejemplos' }, { minutes: 10, activity: 'Autoevaluación', material: 'Responder cinco preguntas y revisar errores' }], totalMinutes: 40 }; break;
  case 'calendar': automation = { type: 'calendar_draft', title: p.subject, description: p.content, attendee: p.recipient || null, status: 'esperando fecha y aprobación' }; break;
}
return [{ json: { ok: true, app: 'NEXORA AI', requestId: p.requestId, action: p.action, label: p.actionLabel, priority: p.priority, approvalRequired: p.approvalRequired, storedLocally: p.storedLocally, message: `${p.actionLabel} preparado correctamente en n8n local`, automation, nextSteps: p.approvalRequired ? ['Revisar destinatario y contenido', 'Aprobar manualmente antes de conectar un servicio real'] : ['Revisar el resultado', 'Continuar el flujo desde NEXORA'] } }];
